"""Synthetic contract examples generated by RLO's actual companion producer."""
import copy
import hashlib
import json
from pathlib import Path
import tempfile
import unittest

import ba_dashboard as d
import ba_facts
import ba_rlo as rlo
from ba_save import Names, load_save
from tests import save_fixtures as f
from tests.es3_fixture import encode
from tests.test_building_facts import facts_for
from tests.test_street_food import load

FIXTURES = Path(__file__).resolve().parents[1] / "contracts" / "rlo"


def report(name="ready"):
    return json.loads((FIXTURES / (name + ".json")).read_text())


def company(block=None, marker=False):
    block = report() if block is None else block
    root = f.data_company(day=12)
    root.update(characterId="fixture-player", SaveGameName="Fixture & Co", Hour=8, Minute=30, buildNumberAtLastSave=2479)
    raw = json.dumps(block, ensure_ascii=False)
    root["modData"] = {rlo.KEY: raw}
    if marker:
        root["modData"][rlo.MARKER] = json.dumps({"status": "fresh", "sha256": hashlib.sha256(raw.encode()).hexdigest()})
    return root


class RloTests(unittest.TestCase):
    def test_producer_fixture_and_ordinary_save_round_trip(self):
        save = load(company())
        self.assertEqual(rlo.read(save)["status"], "ready")
        self.assertEqual(rlo.read(save)["modules"]["employment"]["data"][0]["ordinaryHourlyCents"], 2350)
        self.assertEqual(rlo.metadata(save), {"status": "ready", "source": "save", "version": "fixture-v1",
                         "capabilities": dict.fromkeys(rlo.CAPABILITIES, "ready"),
                         "businesses": 1, "employees": 1, "accounts": 2, "creditAccountBalance": 62000})
        self.assertIs(rlo.read(save), rlo.read(save))
        self.assertEqual(d.ba_mods.detect(save)["rlo"], rlo.metadata(save))

    def test_legacy_and_no_mod_evidence(self):
        root = f.data_company()
        self.assertIsNone(rlo.metadata(load(root)))
        root["modData"] = {"reallife:company": "old private format"}
        self.assertEqual(rlo.metadata(load(root))["status"], "legacy")

    def test_producer_failure_is_local(self):
        data = rlo.read(load(company(report("partial"))))
        self.assertEqual(data["status"], "partial")
        self.assertEqual(data["modules"]["credit"], {"status": "failed"})
        self.assertEqual(data["modules"]["features"], {"status": "disabled"})
        self.assertEqual(data["modules"]["businesses"]["status"], "ready")
        self.assertNotIn("creditAccountBalance", rlo.metadata(load(company(report("partial")))))

    def test_additive_fields_allowed_unknown_versions_ignored_per_capability(self):
        block = report()
        block["extra"] = "future envelope field"
        block["modules"]["future"] = {"version": 5, "status": "ready", "data": {}}
        block["modules"]["employment"]["data"][0]["extra"] = 1
        self.assertEqual(rlo.read(load(company(block)))["status"], "ready")
        for version in (True, 2, None):
            block["modules"]["credit"]["version"] = version
            data = rlo.read(load(company(block)))
            self.assertEqual(data["status"], "partial")
            self.assertEqual(data["modules"]["credit"], {"status": "unavailable"})
            self.assertEqual(data["modules"]["employment"]["status"], "ready")
        block["schemaVersion"] = 2
        self.assertEqual(rlo.read(load(company(block)))["status"], "unavailable")

    def test_live_capture_requires_matching_digest_even_after_portable_export(self):
        for fresh in (False, True):
            root = company(marker=fresh)
            save = load(root)
            save.live_source = True
            self.assertEqual(rlo.read(save)["status"], "ready" if fresh else "stale")
            with tempfile.TemporaryDirectory() as tmp:
                root["modData"] = [{"$k": k, "$v": v} for k, v in root["modData"].items()]
                raw = encode(root)
                path = Path(tmp, "export.bcsave")
                path.write_bytes(ba_facts.pack(raw, facts_for(raw, root)))
                self.assertEqual(rlo.read(load_save(str(path)))["status"], "ready" if fresh else "stale")
        root = company(marker=True)
        root["modData"][rlo.KEY] += " "
        self.assertEqual(rlo.read(load(root))["status"], "stale")
        root = company(marker=True)
        root["modData"][rlo.MARKER] = '{"status":"unavailable"}'
        self.assertEqual(rlo.read(load(root))["status"], "stale")

    def test_fractional_game_minutes_match_the_whole_capture_minute(self):
        root = company()
        root["Minute"] = 30.75
        self.assertEqual(rlo.read(load(root))["status"], "ready")
        for value in (True, "30", None, -1, 60, 31.01):
            root["Minute"] = value
            self.assertEqual(rlo.read(load(root))["status"], "stale")

    def test_capture_identity_must_match_save(self):
        for key, value in (("Day", 13), ("Hour", 9), ("Minute", 31), ("characterId", "other")):
            root = company()
            root[key] = value
            self.assertEqual(rlo.read(load(root))["status"], "stale", key)

    def test_save_fields_finalized_after_save_hook_do_not_invalidate_report(self):
        root = company()
        # SaveGameManager sets these after onSaveGame (Save As and game updates).
        root.update(SaveGameName="Renamed company", buildNumberAtLastSave=9999)
        self.assertEqual(rlo.read(load(root))["status"], "ready")

    def test_nonready_capability_requires_explicit_null_data(self):
        for status in ("disabled", "unavailable", "failed"):
            for data in ([], "missing"):
                block = report()
                module = block["modules"]["credit"]
                module.update(status=status, data=data)
                if data == "missing":
                    del module["data"]
                result = rlo.read(load(company(block)))
                self.assertEqual(result["status"], "partial")
                self.assertEqual(result["modules"]["credit"], {"status": "unavailable"})
                self.assertEqual(result["modules"]["employment"]["status"], "ready")

    def test_malformed_envelopes_and_bounds_fail_closed(self):
        for raw in (None, "{", "[]", '{"schemaVersion":1,"schemaVersion":1}', '{"x":NaN}',
                    "x" * (rlo.MAX_BYTES + 1), "[" * 1100 + "]" * 1100):
            root = company()
            root["modData"][rlo.KEY] = raw
            self.assertEqual(rlo.read(load(root))["status"], "unavailable")
        for name, mutate in (
            ("employment", lambda rows: rows[0].update(ordinaryHourlyCents=1)),
            ("employment", lambda rows: rows[0].update(baseHourlyCents=True)),
            ("employment", lambda rows: rows[0].update(raiseHourlyCents=-1)),
            ("credit", lambda rows: rows[0].update(balanceCents=2**53)),
            ("credit", lambda rows: rows[0].update(includedInGameLoans=True)),
            ("credit", lambda rows: rows.append(copy.deepcopy(rows[0]))),
            ("businesses", lambda rows: rows[0].update(name="x" * 1025)),
            ("features", lambda rows: rows[0].update(running="true")),
        ):
            block = report()
            mutate(block["modules"][name]["data"])
            data = rlo.read(load(company(block)))
            self.assertEqual(data["status"], "partial", name)
            self.assertEqual(data["modules"][name], {"status": "unavailable"})
            self.assertEqual(data["modules"]["accounting"]["status"], "ready")

    def test_empty_is_known_zero_missing_is_unavailable(self):
        block = report()
        block["modules"]["credit"]["data"] = []
        self.assertEqual(rlo.metadata(load(company(block)))["creditAccountBalance"], 0)
        del block["modules"]["credit"]
        self.assertNotIn("creditAccountBalance", rlo.metadata(load(company(block))))

    def test_report_does_not_double_book_costs_or_change_planners(self):
        root = company()
        vanilla = copy.deepcopy(root)
        del vanilla["modData"]
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp, "synthetic.hsg")
            path.write_bytes(encode(vanilla))
            before = d.extract(load_save(str(path)), Names(f.data_names()))
            root["modData"] = [{"$k": k, "$v": v} for k, v in root["modData"].items()]
            path.write_bytes(encode(root))
            after = d.extract(load_save(str(path)), Names(f.data_names()))
            after["meta"]["saved"] = before["meta"]["saved"]
        self.assertEqual(after.pop("mods")["rlo"]["creditAccountBalance"], 62000)
        self.assertEqual(after, before)


if __name__ == "__main__":
    unittest.main()
